import { describe, expect, it } from 'vitest'
import { LINE_TERMINI } from './headways'
import { OBSERVED_GTFS_CAP_S, OBSERVED_GTFS_SCALE, OBSERVED_META, OBSERVED_PROFILE_INTERP_S, OBSERVED_PROFILE_S, OBSERVED_STOP_FACTOR } from './headways.observed'

/*
 * A guard, not a spec of the numbers. The overlay is regenerated by
 * `pnpm --filter api fit:headways` and read by utils/observedHeadways.ts with
 * no validation of its own, so a malformed regeneration should fail here, in
 * CI, instead of reaching the planner.
 */
describe('generated observed headways', () => {
  it('has well-formed profile keys with plausible values', () => {
    const entries = Object.entries(OBSERVED_PROFILE_S)
    expect(entries.length).toBeGreaterThan(0)
    for (const [key, seconds] of entries) {
      const match = /^(WD|WE):(\d{1,2}):([^@]+)@([FR])$/.exec(key)
      expect(match, key).not.toBeNull()
      expect(Number(match![2])).toBeLessThanOrEqual(23)
      expect(seconds, key).toBeGreaterThanOrEqual(120)
      expect(seconds, key).toBeLessThanOrEqual(3600)
      expect(LINE_TERMINI[match![3]!], `${key} is not a TJ corridor`).toBeDefined()
    }
  })

  it('has interpolated cells that are well formed and never overlap a measured one', () => {
    for (const [key, seconds] of Object.entries(OBSERVED_PROFILE_INTERP_S)) {
      expect(key, key).toMatch(/^(WD|WE):\d{1,2}:[^@]+@[FR]$/)
      expect(OBSERVED_PROFILE_S[key], `${key} is both measured and interpolated`).toBeUndefined()
      expect(seconds, key).toBeGreaterThanOrEqual(120)
      expect(seconds, key).toBeLessThanOrEqual(3600)
    }
  })

  it('keeps every interpolated cell inside the range of its own line-direction\'s measured cells', () => {
    // Interpolating or holding can never leave the measured range. A unit mix-up
    // (rate instead of seconds) lands every cell on the clamp floor and fails this.
    const range = new Map<string, { min: number, max: number }>()
    for (const [key, seconds] of Object.entries(OBSERVED_PROFILE_S)) {
      const [dayType, , lineDir] = key.split(':') as [string, string, string]
      const id = `${dayType}:${lineDir}`
      const r = range.get(id) ?? { min: Infinity, max: -Infinity }
      range.set(id, { min: Math.min(r.min, seconds), max: Math.max(r.max, seconds) })
    }
    for (const [key, seconds] of Object.entries(OBSERVED_PROFILE_INTERP_S)) {
      const [dayType, , lineDir] = key.split(':') as [string, string, string]
      const r = range.get(`${dayType}:${lineDir}`)
      expect(r, `${key} has no measured cells to interpolate from`).toBeDefined()
      expect(seconds, key).toBeGreaterThanOrEqual(r!.min - 1)
      expect(seconds, key).toBeLessThanOrEqual(r!.max + 1)
    }
  })

  it('has well-formed stop factors for lines that have a profile', () => {
    const profiled = new Set(Object.keys(OBSERVED_PROFILE_S).map(k => k.split(':')[2]!.replace(/@[FR]$/, '')))
    for (const [key, factor] of Object.entries(OBSERVED_STOP_FACTOR)) {
      expect(key, key).toMatch(/^[^@]+@TJ-[^@]+@[FR]$/)
      expect(Number.isFinite(factor) && factor > 0, key).toBe(true)
      expect(profiled.has(key.slice(0, key.indexOf('@'))), `${key}: its line has no profile in any hour`).toBe(true)
    }
  })

  it('covers every column with a finite positive scale for each day type that has data', () => {
    const dayTypes = new Set(Object.keys(OBSERVED_PROFILE_S).map(k => k.slice(0, 2)))
    for (const dayType of dayTypes) {
      for (let hour = 0; hour < 24; hour++) {
        const scale = OBSERVED_GTFS_SCALE[`${dayType}:${hour}`]
        expect(scale, `${dayType}:${hour}`).toBeDefined()
        expect(Number.isFinite(scale) && scale! > 0, `${dayType}:${hour}`).toBe(true)
      }
    }
  })

  it('has a sane cap wherever there is a scale', () => {
    for (const id of Object.keys(OBSERVED_GTFS_SCALE)) {
      const cap = OBSERVED_GTFS_CAP_S[id]
      expect(cap, id).toBeDefined()
      expect(Number.isFinite(cap) && cap! >= 120, id).toBe(true)
    }
    for (const id of Object.keys(OBSERVED_GTFS_CAP_S)) expect(OBSERVED_GTFS_SCALE[id], `${id} has a cap but no scale`).toBeDefined()
  })

  it('says which range it was fitted on', () => {
    expect(OBSERVED_META.from <= OBSERVED_META.to).toBe(true)
    expect(OBSERVED_META.days.WD).toBeGreaterThan(0)
  })
})
